%% step03_plotGeometryMDSorient_mache_model.m
% =========================================================================
% STEP 3 - Representational geometry analysis for P-only, S-only and Shared
% sEEG contact classes.
%
% INPUT
% -----
% Uses the downstream export generated by the adopted factor-controlled
% classification:
%
%   downstream_analysis_inputs_200ms_50ms\
%       02_geometry_RDM\
%           allResponsive_RDM_part01.mat ... part10.mat
%
% The table allResponsive_RDM contains:
%   Subject | Contact | P_significant | S_significant | UnitClass |
%   RDM_t050ms ... RDM_t800ms
%
% UnitClass:
%   1 = P-only
%   2 = S-only
%   3 = Shared
%
% ANALYSIS PRINCIPLES
% -------------------
% 1) Participant-first aggregation:
%    contacts are averaged within participant first, then participant RDMs
%    are averaged equally at the group level.
%
% 2) Two target windows are shown by default:
%       center 200 ms -> 100-300 ms
%       center 500 ms -> 400-600 ms
%
% 3) Distance summaries use the factor-controlled pair sets:
%       P similar    = P-same / S-different       (26 pairs)
%       P different  = P-different / S-different (650 pairs)
%       S similar    = P-different / S-same       (650 pairs)
%       S different  = P-different / S-different (650 pairs)
%
%    Thus P and S effects are not compared using confounded pair groups.
%
% 4) Model-matched group-RDM analysis. For each class/window, contacts are
%    first averaged within participant and participants are averaged equally.
%    The resulting single group RDM is independently normalized to [0,1].
%    Heatmaps, distance bars, MDS and statistical effects all use that same
%    group RDM. Bar error bars are SD across the relevant stimulus-pair
%    distances (26 or 650 pairs), not SEM across participants.
%
%       P effect = P-different - P-similar
%       S effect = S-different - S-similar
%
%    One-sided significance is obtained from the same 10,000 restricted
%    stimulus-label permutations as the model analysis. P and S are tested
%    at all 16 predefined windows, followed by separate Holm correction
%    across 16 P tests and 16 S tests within each contact class.
%
% 5) MDS:
%    group-level participant-first RAW cosine-distance RDMs -> 2-D metric MDS
%    -> unit-radius normalization -> Procrustes alignment of late to early.
%    A SINGLE final rotation, defined by the LATE semantic-category centroid
%    axis, is applied identically to both time points. The rotation changes
%    orientation only and does not change within-time-point distances.
%
% OUTPUT
% ------
% results_03_geometry\
%   Geometry_Ponly.png/.pdf
%   Geometry_Sonly.png/.pdf
%   Geometry_Shared.png/.pdf
%   Geometry_threeClasses.png/.pdf
%   Geometry_groupRDM_permutation_statistics_16windows.csv
%   Geometry_group_RDM_MDS.mat
%
% =========================================================================

clearvars;
close all;
clc;
set(0,'DefaultFigureVisible','on');

%% ============================ USER SETTINGS =============================

% ------------------------------- Paths -----------------------------------
script_dir = fileparts(mfilename('fullpath'));
input_root = fullfile(fileparts(script_dir), '02_classify_units', ...
    'main_factorControlled_2consecutive_with_downstream', ...
    'downstream_analysis_inputs_200ms_50ms');

plot_root = script_dir;

geometry_dir = fullfile(input_root, '02_geometry_RDM');
geometry_parts = arrayfun( ...
    @(i) fullfile(geometry_dir, sprintf('allResponsive_RDM_part%02d.mat', i)), ...
    1:10, 'UniformOutput', false);

save_dir = fullfile(plot_root,'results_03_geometry_match_model');

if ~isfolder(save_dir)
    mkdir(save_dir);
end

assert(all(cellfun(@isfile, geometry_parts)), ...
    'One or more geometry input parts are missing from: %s', geometry_dir);

% ----------------------------- Time windows ------------------------------
% ALL 16 windows are used for statistical inference.
time_points = 50:50:800;
n_all_windows = numel(time_points);
window_width_ms = 200;

% Only these windows are DISPLAYED in the main geometry figure.
% Their p-values are taken from the full 16-window analysis below.
target_centers = [200 500];

assert(all(ismember(target_centers,time_points)), ...
    'Every target center must be one of: %s',mat2str(time_points));

target_window_labels = arrayfun( ...
    @(x) sprintf('%d-%d ms', ...
    x-window_width_ms/2, ...
    x+window_width_ms/2), ...
    target_centers, ...
    'UniformOutput',false);

all_window_labels = arrayfun( ...
    @(x) sprintf('%d-%d ms', ...
    x-window_width_ms/2, ...
    x+window_width_ms/2), ...
    time_points, ...
    'UniformOutput',false);

all_rdm_var_names = cellstr(compose('RDM_t%03dms',time_points));

[tf_target,target_window_idx] = ismember(target_centers,time_points);

assert(all(tf_target), ...
    'Could not map target_centers into the complete time_points vector.');

% ----------------------------- Contact classes ---------------------------
class_codes = [1 2 3];

class_names = { ...
    'Phonological', ...
    'Semantic', ...
    'Shared'};

class_file_tags = { ...
    'Ponly', ...
    'Sonly', ...
    'Shared'};

% ------------------------------- Colors ----------------------------------
P_sim_color  = [203  43  35]/255;
P_diff_color = [234 139 134]/255;

S_sim_color  = [  2  88 166]/255;
S_diff_color = [112 166 202]/255;

edible_color   = [ 20 174 181]/255;
inedible_color = [243 169  55]/255;

% RDM display colormap: use the same custom 5-node gradient as the
% previous RDM plotting code.
color1 = [50, 28, 90] / 255;    % dark purple-blue
color2 = [40, 100, 120] / 255;  % teal
color3 = [45, 175, 120] / 255;  % green
color4 = [170, 215, 60] / 255;  % lime
color5 = [252, 245, 65] / 255;  % yellow

control_colors = [color1; color2; color3; color4; color5];
rdm_cmap = interp1( ...
    linspace(1,5,5), ...
    control_colors, ...
    linspace(1,5,256));

% Normalize EACH RDM independently to [0,1] for heatmap display.
% The minimum and maximum are computed from the finite OFF-DIAGONAL values
% of that RDM itself, so the minimum displayed distance maps to 0 and the
% maximum displayed distance maps to 1.
% All MDS and statistical calculations still use RAW cosine distances.
normalize_heatmaps_for_display = true;

% Distance-summary bars use the SAME independently normalized group RDM as
% the heatmap above them. No participant RDM is treated as a statistical
% replicate in this model-matched version.
distance_summary_use_normalized = true;

% ------------------------------- Statistics ------------------------------
geometry_alpha = 0.05;
num_permutations = 10000;
permutation_seed = 20260918;

% true  = correct across the FULL 16-window series
% false = use nominal, uncorrected p-values
use_multiple_comparison_correction = true;

% Used only when the switch above is true:
%   'holm'        -> Holm-Bonferroni FWER
%   'bonferroni'  -> Bonferroni FWER
%   'fdr'         -> Benjamini-Hochberg FDR
geometry_correction = 'holm';

% P and S are treated as two predefined representational hypotheses.
% Correction is therefore applied separately across:
%   16 P-window tests
%   16 S-window tests
% within each contact class.
correction_family = 'separate_P_and_S_across_16_windows';

% ------------------------------- MDS style -------------------------------
% FINAL embedding method: metric MDS on the RAW group cosine-distance RDM.
% Do NOT feed the display-normalized RDM into MDS.
mds_seed = 20260920;
mds_time_spacing = 1.8;

% Horizontal compression for the FINAL visualization.
% This intentionally compresses the whole 2-D point cloud, trajectories,
% and highlighted markers along x so the representation is displayed as a
% tall ellipse, matching the original figure style.
% Try 0.32-0.50 if you want a narrower/wider ellipse.
mds_x_compression = 0.50;
mds_y_stretch = 1.30;

normal_marker_size = 12;
special_marker_size = 42;

% ----------------------- MANUAL example word pairs -----------------------
word_names = default_word_names_52();

% We now MANUALLY choose the three phonologically matched example pairs.
% The MDS calculation itself is completely unchanged by this choice; these
% pairs only determine which six points receive diamond/square/circle markers.
%
% Each row below is one phonologically matched pair:
%       first-column word     second-column word
%
% To try another combination, directly replace the three rows below.
% The code checks that the two words in every row are a true i <-> i+26 pair.
%
% -------------------------------------------------------------------------
% All 26 valid phonological pairs in the current stimulus order:
%
%   草莓 / 草坪        带鱼 / 代表        蛋糕 / 弹弓
%   豆腐 / 逗号        海带 / 海滩        红薯 / 红灯
%   鸡蛋 / 机会        煎饼 / 肩膀        荔枝 / 力量
%   龙虾 / 笼子        萝卜 / 螺旋        绿豆 / 律师
%   芒果 / 盲人        蜜桔 / 密码        面包 / 面具
%   蘑菇 / 模特        牛肉 / 牛仔        苹果 / 评委
%   软糖 / 软件        薯条 / 暑假        西瓜 / 膝盖
%   香肠 / 乡村        洋葱 / 阳光        樱桃 / 英雄
%   玉米 / 浴室        猪蹄 / 珠宝
% -------------------------------------------------------------------------
%
% MANUAL example pairs to highlight in the MDS plots.
%
% IMPORTANT:
% - Only ONE set of three pairs is used each time.
% - If you want to try another combination, directly replace the 3 rows below.
% - The code checks that each row is a true phonological pair (i and i+26).
%
% Example format:
% manual_pair_words = [ ...
%     "草莓","草坪"; ...
%     "蛋糕","弹弓"; ...
%     "玉米","浴室"];
%
% Recommended workflow:
% keep rerunning the script after replacing these three rows, until the
% highlighted examples look best in the Shared-contact panel.
manual_pair_words = [ ...
    "煎饼","肩膀"; ...
    "蜜桔","密码"; ...
    "蘑菇","模特"];

% Fixed marker mapping for the 3 manually selected pairs:
% row 1 = diamond, row 2 = square, row 3 = circle
special_shapes = {'d','s','o'};

% ------------------------------- Figure ----------------------------------
save_png = true;
save_pdf = true;
png_resolution = 600;

individual_position = [100 60 300 500];
combined_position   = [100 40 980 660];

% ===================== MANUAL PANEL SIZE SETTINGS =====================
% These settings control the THREE rows in each individual-class figure.
% Position units are normalized figure coordinates.
%
% RDM row
rdm_panel_size = [0.235 0.235];   % [width height]
rdm_row_y      = 0.72;          % vertical position
%
% Bar row
bar_panel_size = [0.235 0.15];   % [width height]
bar_row_y      = 0.50;          % vertical position
%
% MDS row
mds_panel_size = [0.83 0.42];   % [width height]
mds_row_y      = 0.06;          % vertical position
%
% Horizontal positions
left_col_x  = 0.13;
right_col_x = 0.55;
mds_left_x  = 0.10;
% =====================================================================

%% ============================== LOAD DATA ================================

for ipart = 1:numel(geometry_parts)
    S = load(geometry_parts{ipart}, 'allResponsive_RDM');
    assert(isfield(S, 'allResponsive_RDM'), ...
        'Variable allResponsive_RDM is missing from: %s', geometry_parts{ipart});
    if ipart == 1
        RDM_table = S.allResponsive_RDM;
    else
        RDM_table = [RDM_table; S.allResponsive_RDM]; %#ok<AGROW>
    end
end
assert(height(RDM_table) == 894, 'Expected 894 responsive-contact rows.');

assert(istable(RDM_table), ...
    'allResponsive_RDM must be a MATLAB table.');

required_meta = { ...
    'Subject', ...
    'Contact', ...
    'P_significant', ...
    'S_significant', ...
    'UnitClass'};

assert(all(ismember(required_meta,RDM_table.Properties.VariableNames)), ...
    'allResponsive_RDM is missing one or more metadata columns.');

assert(all(ismember(all_rdm_var_names,RDM_table.Properties.VariableNames)), ...
    'One or more of the 16 RDM columns are missing from allResponsive_RDM.');

fprintf('\n============================================================\n');
fprintf('STEP 3 REPRESENTATIONAL GEOMETRY\n');
fprintf('============================================================\n');
fprintf('Loaded %d responsive contacts.\n',height(RDM_table));
fprintf('Target windows: %s and %s\n', ...
    target_window_labels{1},target_window_labels{2});

%% ============================ PAIR MASKS =================================

masks = build_factor_controlled_masks(52);
[P_weights,S_weights] = restricted_permutation_weights( ...
    num_permutations,permutation_seed);

fprintf('\nPair counts used for geometry summaries:\n');
fprintf('  P-same / S-different       : %d\n',nnz(masks.P_sim));
fprintf('  P-different / S-different : %d\n',nnz(masks.P_diff));
fprintf('  P-different / S-same      : %d\n',nnz(masks.S_sim));
fprintf('  P-different / S-different : %d\n',nnz(masks.S_diff));

%% ================= GROUP-RDM GEOMETRY AND PERMUTATION ====================

Geometry = struct();

for iclass = 1:numel(class_codes)

    cls = class_codes(iclass);

    use_class = RDM_table.UnitClass==cls;
    Tclass = RDM_table(use_class,:);

    subjects_here = unique(string(Tclass.Subject),'stable');

    fprintf('\n%s contacts: %d contacts | %d participants\n', ...
        class_names{iclass},height(Tclass),numel(subjects_here));

    Geometry(iclass).ClassCode = cls;
    Geometry(iclass).ClassName = class_names{iclass};
    Geometry(iclass).NContacts = height(Tclass);
    Geometry(iclass).Subjects = subjects_here;
    Geometry(iclass).NParticipants = numel(subjects_here);

    raw_p_P = nan(1,n_all_windows);
    raw_p_S = nan(1,n_all_windows);

    % ---------------------------------------------------------------------
    % A. Compute the participant-first group RDM at all 16 windows.  All
    %    displayed distances and inferential effects are then taken from
    %    this single group RDM, matching the model analysis.
    % ---------------------------------------------------------------------
    for iw = 1:n_all_windows

        varname = all_rdm_var_names{iw};

        [subjects_window,subject_rdms,group_rdm] = ...
            participant_first_rdm(Tclass,varname);

        assert(isequal(subjects_here,subjects_window), ...
            'Unexpected subject mismatch across RDM windows.');

        if distance_summary_use_normalized
            group_rdm_for_summary = normalize_rdm_for_display(group_rdm);
        else
            group_rdm_for_summary = group_rdm;
        end

        summary = summarize_group_rdm(group_rdm_for_summary,masks);
        [raw_p_P(iw),raw_p_S(iw)] = restricted_permutation_pvalues( ...
            group_rdm_for_summary,P_weights,S_weights,summary);

        Geometry(iclass).AllWindows(iw).CenterMs = time_points(iw);
        Geometry(iclass).AllWindows(iw).Label = all_window_labels{iw};
        Geometry(iclass).AllWindows(iw).SubjectRDMs = subject_rdms;
        Geometry(iclass).AllWindows(iw).GroupRDM = group_rdm;
        Geometry(iclass).AllWindows(iw).Summary = summary;
    end

    % ---------------------------------------------------------------------
    % B. Multiple-comparison correction across the FULL 16-window series.
    %
    %    P family = 16 P-window tests
    %    S family = 16 S-window tests
    %
    %    P and S are corrected separately.
    % ---------------------------------------------------------------------
    if use_multiple_comparison_correction

        adj_p_P = adjust_pvalues( ...
            raw_p_P, ...
            geometry_correction);

        adj_p_S = adjust_pvalues( ...
            raw_p_S, ...
            geometry_correction);

    else

        adj_p_P = raw_p_P;
        adj_p_S = raw_p_S;
    end

    for iw = 1:n_all_windows

        Geometry(iclass).AllWindows(iw).Summary.P_p_raw = raw_p_P(iw);
        Geometry(iclass).AllWindows(iw).Summary.S_p_raw = raw_p_S(iw);

        Geometry(iclass).AllWindows(iw).Summary.P_p_adj = adj_p_P(iw);
        Geometry(iclass).AllWindows(iw).Summary.S_p_adj = adj_p_S(iw);
    end

    Geometry(iclass).P_p_raw_16 = raw_p_P;
    Geometry(iclass).S_p_raw_16 = raw_p_S;
    Geometry(iclass).P_p_forPlot_16 = adj_p_P;
    Geometry(iclass).S_p_forPlot_16 = adj_p_S;

    % ---------------------------------------------------------------------
    % C. Extract the requested display windows.
    %    Their p-values are inherited from the 16-window analysis above.
    % ---------------------------------------------------------------------
    for idisplay = 1:numel(target_centers)

        iall = target_window_idx(idisplay);

        Geometry(iclass).Window(idisplay) = ...
            Geometry(iclass).AllWindows(iall);
    end

    % MDS is needed only for the displayed windows.
    rng(mds_seed + iclass,'twister');

    [Yearly,Ylate] = aligned_mds_pair( ...
        Geometry(iclass).Window(1).GroupRDM, ...
        Geometry(iclass).Window(2).GroupRDM);

    Geometry(iclass).MDS.Early = Yearly;
    Geometry(iclass).MDS.Late = Ylate;
end

%% ====================== MANUAL EXAMPLE PAIR SELECTION ====================
% Convert the manually written word names into the 52-word stimulus indices.
% This only controls marker shapes in the MDS visualization.

selected_pair_words = manual_pair_words;

[special_pairs,special_pair_labels] = manual_pair_words_to_indices( ...
    selected_pair_words, ...
    word_names, ...
    true);   % true = require a valid i <-> i+26 phonological pair

assert(size(special_pairs,1)==3, ...
    'Exactly 3 manual pairs are required because three marker shapes are used.');

fprintf('\n============================================================\n');
fprintf('MANUALLY SELECTED MDS EXAMPLE PAIRS\n');
fprintf('============================================================\n');
for ip = 1:size(special_pairs,1)
    fprintf('  Pair %d [%s]: %s / %s  (indices %d / %d)\n', ...
        ip,special_shapes{ip}, ...
        selected_pair_words(ip,1),selected_pair_words(ip,2), ...
        special_pairs(ip,1),special_pairs(ip,2));
end

% No automatic pair ranking is used in this manual-selection version.
% The three highlighted pairs above are the only pair-selection input.

%% ======================== RDM DISPLAY NORMALIZATION =====================
%
% IMPORTANT:
% Each RDM is normalized independently to [0,1] only when it is plotted.
% No color-scale range is shared across contact classes or time windows.
% MDS uses the original group cosine-distance RDM; distance bars and
% permutation statistics use the independently normalized version of that
% same group RDM.

% Common y-axis for all distance bar plots.
all_bar_top = [];

for iclass = 1:numel(class_codes)

    for iw = 1:numel(target_centers)

        Q = Geometry(iclass).Window(iw).Summary;

        bar_mean = [ ...
            mean(Q.P_sim,'omitnan'), ...
            mean(Q.P_diff,'omitnan'), ...
            mean(Q.S_sim,'omitnan'), ...
            mean(Q.S_diff,'omitnan')];

        bar_sd = [ ...
            std_1d(Q.P_sim), ...
            std_1d(Q.P_diff), ...
            std_1d(Q.S_sim), ...
            std_1d(Q.S_diff)];

        all_bar_top = [all_bar_top,bar_mean+bar_sd]; %#ok<AGROW>
    end
end

bar_data_max = max(all_bar_top,[],'omitnan'); %#ok<NASGU>

% Group RDM distances are normalized to [0,1].
bar_ylim = [0 1];

%% ======================== GROUP-RDM STATISTICS TABLE =====================
%
% Save ALL 16 windows so the full correction family is explicit.

stats_table = table();

for iclass = 1:numel(class_codes)

    for iw = 1:n_all_windows

        Q = Geometry(iclass).AllWindows(iw).Summary;

        row = table( ...
            string(class_names{iclass}), ...
            class_codes(iclass), ...
            time_points(iw), ...
            string(all_window_labels{iw}), ...
            ismember(iw,target_window_idx), ...
            Geometry(iclass).NParticipants, ...
            mean(Q.P_sim,'omitnan'), ...
            std_1d(Q.P_sim), ...
            mean(Q.P_diff,'omitnan'), ...
            std_1d(Q.P_diff), ...
            mean(Q.S_sim,'omitnan'), ...
            std_1d(Q.S_sim), ...
            mean(Q.S_diff,'omitnan'), ...
            std_1d(Q.S_diff), ...
            Q.P_effect, ...
            Q.P_p_raw, ...
            Q.P_p_adj, ...
            Q.S_effect, ...
            Q.S_p_raw, ...
            Q.S_p_adj, ...
            correction_label( ...
                use_multiple_comparison_correction, ...
                geometry_correction), ...
            string(correction_family), ...
            string('SD across stimulus-pair distances'), ...
            int32(num_permutations), ...
            'VariableNames',{ ...
            'ContactClass', ...
            'ClassCode', ...
            'WindowCenter_ms', ...
            'WindowLabel', ...
            'DisplayedInMainFigure', ...
            'N_participants', ...
            'P_similar_mean', ...
            'P_similar_SD', ...
            'P_different_mean', ...
            'P_different_SD', ...
            'S_similar_mean', ...
            'S_similar_SD', ...
            'S_different_mean', ...
            'S_different_SD', ...
            'P_effect_diffMinusSimilar', ...
            'P_p_raw', ...
            'P_p_forPlot', ...
            'S_effect_diffMinusSimilar', ...
            'S_p_raw', ...
            'S_p_forPlot', ...
            'CorrectionMethod', ...
            'CorrectionFamily', ...
            'ErrorBarDefinition', ...
            'NPermutations'});

        stats_table = [stats_table;row]; %#ok<AGROW>
    end
end

stats_csv = fullfile( ...
    save_dir, ...
    'Geometry_groupRDM_permutation_statistics_16windows.csv');

writetable(stats_table,stats_csv);

%% ======================== INDIVIDUAL CLASS FIGURES =======================

for iclass = 1:numel(class_codes)

    h = figure( ...
        'Color','w', ...
        'Position',individual_position, ...
        'Renderer','painters');

    % ----------------------- Manual panel layout -------------------------
    % Sizes are controlled by the settings near the top of this script.
    ax1 = axes(h,'Position',[ ...
        left_col_x, rdm_row_y, rdm_panel_size(1), rdm_panel_size(2)]);

    % ----------------------------- RDMs -----------------------------------
    plot_rdm_triangle( ...
        ax1, ...
        Geometry(iclass).Window(1).GroupRDM, ...
        normalize_heatmaps_for_display, ...
        rdm_cmap);

    title(ax1,target_window_labels{1}, ...
        'FontName','Arial', ...
        'FontSize',7, ...
        'FontWeight','normal');

    ax2 = axes(h,'Position',[ ...
        right_col_x, rdm_row_y, rdm_panel_size(1), rdm_panel_size(2)]);
    plot_rdm_triangle( ...
        ax2, ...
        Geometry(iclass).Window(2).GroupRDM, ...
        normalize_heatmaps_for_display, ...
        rdm_cmap);

    title(ax2,target_window_labels{2}, ...
        'FontName','Arial', ...
        'FontSize',7, ...
        'FontWeight','normal');

% Keep the right RDM the same size as the left RDM
ax2_pos = ax2.Position;

cb = colorbar(ax2);
cb.FontName = 'Arial';
cb.FontSize = 7;

ax2.Position = ax2_pos;

    if normalize_heatmaps_for_display
        cb.Label.String = 'Normalized cosine distance';
    else
        cb.Label.String = 'Cosine distance';
    end

    cb.Label.FontName = 'Arial';
    cb.Label.FontSize = 7;

    % ------------------------ Distance summaries --------------------------
    ax3 = axes(h,'Position',[ ...
        left_col_x, bar_row_y, bar_panel_size(1), bar_panel_size(2)]);
    plot_distance_summary( ...
        ax3, ...
        Geometry(iclass).Window(1).Summary, ...
        bar_ylim, ...
        geometry_alpha, ...
        P_sim_color, ...
        P_diff_color, ...
        S_sim_color, ...
        S_diff_color);


    ax4 = axes(h,'Position',[ ...
        right_col_x, bar_row_y, bar_panel_size(1), bar_panel_size(2)]);
    plot_distance_summary( ...
        ax4, ...
        Geometry(iclass).Window(2).Summary, ...
        bar_ylim, ...
        geometry_alpha, ...
        P_sim_color, ...
        P_diff_color, ...
        S_sim_color, ...
        S_diff_color);


    % -------------------------- MDS transition ----------------------------
    ax5 = axes(h,'Position',[ ...
        mds_left_x, mds_row_y, mds_panel_size(1), mds_panel_size(2)]);

    plot_mds_transition( ...
        ax5, ...
        Geometry(iclass).MDS.Early, ...
        Geometry(iclass).MDS.Late, ...
        edible_color, ...
        inedible_color, ...
        special_pairs, ...
        special_shapes, ...
        normal_marker_size, ...
        special_marker_size, ...
        mds_time_spacing, ...
        mds_x_compression, ...
        mds_y_stretch);

    sgtitle(h, ...
        sprintf('%s contacts (n = %d; %d participants)', ...
        class_names{iclass}, ...
