function masks = build_factor_controlled_masks(nwords)
% Build lower-triangle masks for the 52-word design.
%
% 1:26  = semantic category 1
% 27:52 = semantic category 2
% pair i <-> i+26 is P-same / S-different.

assert(nwords==52, ...
    'This mask definition expects exactly 52 words.');

lower = tril(true(nwords),-1);

sem_label = [ones(26,1);2*ones(26,1)];
same_sem = sem_label==sem_label';

P_same = false(nwords);

for i = 1:26
    P_same(i+26,i) = true;
end

P_same = P_same & lower;

% P-same / S-different: 26 matched cross-category pairs.
masks.P_sim = P_same;

% P-different / S-same: all within-category unique pairs.
masks.S_sim = same_sem & lower;

% P-different / S-different: cross-category pairs excluding P matches.
masks.P_diff = (~same_sem) & lower & (~P_same);

% Same controlled baseline for semantic contrast.
masks.S_diff = masks.P_diff;

assert(nnz(masks.P_sim)==26, ...
    'Expected 26 P-similar pairs.');

assert(nnz(masks.S_sim)==650, ...
    'Expected 650 S-similar/P-different pairs.');

assert(nnz(masks.P_diff)==650, ...
    'Expected 650 P-different/S-different pairs.');

end


function [subjects_here,subject_rdms,group_rdm] = ...
    participant_first_rdm(Tclass,varname)
% Average contacts within participant first, then average participants.

subjects_here = unique(string(Tclass.Subject),'stable');

nsub = numel(subjects_here);

subject_rdms = cell(nsub,1);

for isub = 1:nsub

    this_subject = subjects_here(isub);

    use_sub = string(Tclass.Subject)==this_subject;

    C = Tclass.(varname);
    C = C(use_sub);

    mats = [];

    for i = 1:numel(C)

        R = complete_rdm(C{i});

        if isempty(mats)
            mats = nan(size(R,1),size(R,2),numel(C));
        end

        mats(:,:,i) = R;
    end

    subject_rdms{isub} = mean(mats,3,'omitnan');
end

stack = nan(52,52,nsub);

for isub = 1:nsub
    stack(:,:,isub) = subject_rdms{isub};
end

group_rdm = mean(stack,3,'omitnan');
group_rdm = complete_rdm(group_rdm);

end


function R = complete_rdm(R)
% Robustly symmetrize a 52x52 RDM while preserving available values.

assert(isnumeric(R) && isequal(size(R),[52 52]), ...
    'Each RDM must be a numeric 52x52 matrix.');

R = double(R);

for i = 1:52

    for j = 1:i-1

        a = R(i,j);
        b = R(j,i);

        if isfinite(a) && isfinite(b)

            v = mean([a b]);

        elseif isfinite(a)

            v = a;

        elseif isfinite(b)

            v = b;

        else

            v = NaN;
        end

        R(i,j) = v;
        R(j,i) = v;
    end
end

R(1:53:end) = 0;

end


function Q = summarize_group_rdm(R,masks)
% Keep the individual pair distances from the single group RDM.  Bar means
% and SDs are calculated across these values, exactly as in the model code.

R = complete_rdm(R);
Q.P_sim  = R(masks.P_sim);
Q.P_diff = R(masks.P_diff);
Q.S_sim  = R(masks.S_sim);
Q.S_diff = R(masks.S_diff);

Q.P_effect = mean(Q.P_diff,'omitnan')-mean(Q.P_sim,'omitnan');
Q.S_effect = mean(Q.S_diff,'omitnan')-mean(Q.S_sim,'omitnan');

Q.P_p_raw = NaN;
Q.S_p_raw = NaN;
Q.P_p_adj = NaN;
Q.S_p_adj = NaN;

end


function [pP,pS] = restricted_permutation_pvalues(R,P_weights,S_weights,Q)
% One-sided p-values for the fixed group RDM under the restricted label
% permutation schemes used by the human classifier and model geometry code.

lower = tril(true(52),-1);
y = single(R(lower));

assert(all(isfinite(y)), ...
    'The group RDM contains NaN/Inf in its lower triangle.');

poolP = double(y'*P_weights);
poolS = double(y'*S_weights);

assert(abs(poolP(1)-Q.P_effect)<1e-6, ...
    'P permutation contrast does not match the displayed P effect.');
assert(abs(poolS(1)-Q.S_effect)<1e-6, ...
    'S permutation contrast does not match the displayed S effect.');

pP = (1+nnz(poolP(2:end)>=poolP(1)))/size(P_weights,2);
pS = (1+nnz(poolS(2:end)>=poolS(1)))/size(S_weights,2);

end


function [P_weights,S_weights] = restricted_permutation_weights(B,seed)
% Exact restricted nulls used by the factor-controlled classification.
% P: keep semantic groups fixed and randomly rematch the 26 cross-category
%    phonological pairs.
% S: preserve every true P pair and independently swap semantic membership
%    within each pair.

rng(seed,'twister');
n = 52;
lower = tril(true(n),-1);
[pair_row,pair_col] = find(lower);
npairs = numel(pair_row);

pair_index = zeros(n);
for k = 1:npairs
    pair_index(pair_row(k),pair_col(k)) = k;
end

semantic = uint8([ones(26,1);2*ones(26,1)]);
cross = semantic(pair_row)~=semantic(pair_col);

true_P = false(npairs,1);
for i = 1:26
    true_P(pair_index(i+26,i)) = true;
end

P_weights = zeros(npairs,B+1,'single');
pairings = zeros(26,B+1,'uint8');
pairings(:,1) = uint8(1:26);

for b = 2:B+1
    pairings(:,b) = uint8(randperm(26));
end

for b = 1:B+1
    w = zeros(npairs,1,'single');
    w(cross) = single(1/650);
    pairing = double(pairings(:,b));
    for i = 1:26
        w(pair_index(26+pairing(i),i)) = single(-1/26);
    end
    P_weights(:,b) = w;
end

S_weights = zeros(npairs,B+1,'single');
flips = false(26,B+1);

for b = 2:B+1
    flips(:,b) = rand(26,1)<0.5;
end

for b = 1:B+1
    labels = zeros(n,1,'uint8');
    for i = 1:26
        if ~flips(i,b)
            labels(i) = 1;
            labels(i+26) = 2;
        else
            labels(i) = 2;
            labels(i+26) = 1;
        end
    end
    within = labels(pair_row)==labels(pair_col);
    between_diffP = ~within & ~true_P;
    w = zeros(npairs,1,'single');
    w(between_diffP) = single(1/650);
    w(within) = single(-1/650);
    S_weights(:,b) = w;
end

end


function [Y1,Y2] = aligned_mds_pair(R1,R2)
% Metric MDS visualization from RAW cosine-distance RDMs.
%
% Pipeline:
%   raw RDM -> 2-D metric MDS -> unit-radius normalization
%   -> Procrustes align late to early
%   -> ONE COMMON rotation determined by the LATE semantic centroid axis.
%
% The common final rotation changes orientation only; it does not alter any
% within-time-point pairwise Euclidean distances.

R1 = complete_rdm(R1);
R2 = complete_rdm(R2);

R1 = max(R1,0);
R2 = max(R2,0);

% Metric MDS on the RAW cosine-distance RDM.
% 'stress' directly fits the supplied dissimilarities in metric form.
[Y1,~] = mdscale(R1,2,'Criterion','stress');
[Y2,~] = mdscale(R2,2,'Criterion','stress');

Y1 = normalize_mds(Y1);
Y2 = normalize_mds(Y2);

% Align the late geometry to the early geometry without scaling.
[~,Y2] = procrustes( ...
    Y1, ...
    Y2, ...
    'Scaling',false, ...
    'Reflection',true);

% Recenter both embeddings after Procrustes.
Y1 = Y1-mean(Y1,1);
Y2 = Y2-mean(Y2,1);

% Use ONE common isotropic scale across both time points.
maxrad = max([ ...
    sqrt(sum(Y1.^2,2)); ...
    sqrt(sum(Y2.^2,2))]);

if maxrad<=eps
    maxrad = 1;
end

Y1 = Y1/maxrad;
Y2 = Y2/maxrad;

% -------------------------------------------------------------------------
% Common orientation determined from the LATE semantic-category axis only.
% This makes the late semantic organization consistent across contact classes:
% yellow (category 2) above, green (category 1) below. The SAME rotation is
% applied to the early geometry; point distances are not changed.
% -------------------------------------------------------------------------
cent_edible_late = mean(Y2(1:26,:),1);
cent_inedible_late = mean(Y2(27:52,:),1);

diff_vec = cent_edible_late-cent_inedible_late;

if norm(diff_vec)>eps

    current_angle = atan2(diff_vec(2),diff_vec(1));

    % The category-1 minus category-2 centroid vector points downward: green below, yellow above.
    target_angle = -pi/2;
    % Y is stored as row vectors and multiplied on the right (Y*Rot),
    % so use current_angle - target_angle for the desired final orientation.
    theta = current_angle-target_angle;

    Rot = [ ...
        cos(theta), -sin(theta); ...
        sin(theta),  cos(theta)];

    Y1 = Y1*Rot;
    Y2 = Y2*Rot;
end

end


function Y = normalize_mds(Y)

Y = Y-mean(Y,1);

r = max(sqrt(sum(Y.^2,2)));

if r<=eps
    r = 1;
end

Y = Y/r;

end


function [Rnorm,rdm_min,rdm_max] = normalize_rdm_for_display(R)
% Normalize one complete 52x52 RDM to [0,1] using its own finite
% OFF-DIAGONAL values. The returned min/max are the raw cosine-distance
% limits used for the transform.
%
% This helper is used by the automatic phonological-pair ranking so that
% the reported NormalizedDistance values are on exactly the same scale as
% the corresponding displayed RDM.

R = complete_rdm(R);

offdiag_mask = tril(true(size(R)),-1);
offdiag_values = R(offdiag_mask);
offdiag_values = offdiag_values(isfinite(offdiag_values));

if isempty(offdiag_values)
    error('RDM contains no finite off-diagonal values.');
end

rdm_min = min(offdiag_values);
rdm_max = max(offdiag_values);

if rdm_max > rdm_min
    Rnorm = (R-rdm_min)/(rdm_max-rdm_min);
else
    Rnorm = zeros(size(R));
end

% Keep the diagonal at zero for a proper distance matrix/display.
Rnorm(1:size(R,1)+1:end) = 0;

end


function plot_rdm_triangle( ...
    ax,R,do_normalize,cmap)
% Plot lower triangle of one group RDM.
%
% If normalization is enabled, THIS RDM is independently rescaled to [0,1]
% using its finite off-diagonal values:
%
%       R_norm = (R - R_min) / (R_max - R_min)
%
% Thus every displayed RDM uses its own min/max color scale. This
% normalization is visualization-only; the original raw cosine-distance
% values are used for MDS and statistical analyses.

R = complete_rdm(R);

[Rnorm,rdm_min,rdm_max] = normalize_rdm_for_display(R);

if do_normalize

    Rplot = Rnorm;
    clim = [0 1];

else

    Rplot = R;

    if rdm_max > rdm_min
        clim = [rdm_min rdm_max];
    else
        clim = [rdm_min rdm_min+eps];
    end
end

mask = tril(true(52),-1);

D = nan(52);
D(mask) = Rplot(mask);

imagesc(ax,1:52,1:52,D, ...
    'AlphaData',isfinite(D));

set(ax, ...
    'Color','w', ...
    'YDir','reverse', ...
    'FontName','Arial', ...
    'FontSize',7, ...
    'TickDir','out', ...
    'TickLength',[0 0], ...
    'LineWidth',0.5, ...
    'Box','on', ...
    'XTick',[], ...
    'YTick',[]);

axis(ax,'square');
xlim(ax,[0.5 52.5]);
ylim(ax,[0.5 52.5]);

colormap(ax,cmap);
caxis(ax,clim);

end


function plot_distance_summary( ...
    ax,Q,yl,alpha,P_sim_color,P_diff_color,S_sim_color,S_diff_color)
% Four bars = factor-controlled P and S pair distances.
% Error bars = SD across stimulus-pair distances in the group RDM.
% Significance = restricted label-permutation p stored in Q.

means = [ ...
    mean(Q.P_sim,'omitnan'), ...
    mean(Q.P_diff,'omitnan'), ...
    mean(Q.S_sim,'omitnan'), ...
    mean(Q.S_diff,'omitnan')];

sds = [ ...
    std_1d(Q.P_sim), ...
    std_1d(Q.P_diff), ...
    std_1d(Q.S_sim), ...
    std_1d(Q.S_diff)];

x = [1.00 1.68 2.82 3.50];

colors = [ ...
    P_sim_color; ...
    P_diff_color; ...
    S_sim_color; ...
    S_diff_color];

hold(ax,'on');

for i = 1:4

    bar( ...
        ax, ...
        x(i), ...
        means(i), ...
        0.52, ...
        'FaceColor',colors(i,:), ...
        'EdgeColor','none');

    errorbar( ...
        ax, ...
        x(i), ...
        means(i), ...
        sds(i), ...
        'k', ...
        'LineStyle','none', ...
        'LineWidth',0.55, ...
        'CapSize',0);
end

ylim(ax,yl);
xlim(ax,[0.55 3.95]);

set(ax, ...
    'FontName','Arial', ...
    'FontSize',7, ...
    'TickDir','out', ...
    'LineWidth',0.5, ...
    'Box','off', ...
    'XTick',[], ...
    'XTickLabel',[], ...
    'YTick',[0 1], ...
    'XColor','k', ...
    'YColor','k');

ylabel(ax,'Normalized distance', ...
    'FontName','Arial', ...
    'FontSize',7);

yr = yl(2)-yl(1);

hP = max(means(1:2)+sds(1:2)) + 0.055*yr;
hS = max(means(3:4)+sds(3:4)) + 0.055*yr;

draw_sig_bracket(ax,x(1),x(2),hP,Q.P_p_adj,alpha);
draw_sig_bracket(ax,x(3),x(4),hS,Q.S_p_adj,alpha);

hold(ax,'off');

end


function draw_sig_bracket(ax,x1,x2,y,p,alpha)

if ~isfinite(p)
    return;
end

yl = ylim(ax);

plot(ax,[x1 x2], ...
    [y y], ...
    '-', ...
    'Color','k', ...
    'LineWidth',0.5, ...
    'HandleVisibility','off');

if p < alpha

    if p < 0.001
        txt = '***';
    elseif p < 0.01
        txt = '**';
    else
        txt = '*';
    end

else

    txt = 'n.s.';
end

text( ...
    ax, ...
    (x1+x2)/2, ...
    y+0.006*(yl(2)-yl(1)), ...
    txt, ...
    'HorizontalAlignment','center', ...
    'VerticalAlignment','bottom', ...
    'FontName','Arial', ...
    'FontSize',7);

end


function plot_mds_transition( ...
    ax,Y1,Y2,edible_color,inedible_color, ...
    special_pairs,special_shapes,normal_marker_size,special_marker_size, ...
    time_spacing,x_compression,y_stretch)
% Two-stage MDS trajectory, visually analogous to the reference figure.

nwords = 52;

X = zeros(nwords,2);
Y = zeros(nwords,2);

X(:,1) = Y1(:,1)*x_compression;
Y(:,1) = Y1(:,2)*y_stretch;

X(:,2) = Y2(:,1)*x_compression + time_spacing;
Y(:,2) = Y2(:,2)*y_stretch;

hold(ax,'on');

% Connections first.
for i = 1:nwords

    if i<=26
        base_color = edible_color;
    else
        base_color = inedible_color;
    end

    line_color = 0.62*base_color + 0.38*[1 1 1];

    plot( ...
        ax, ...
        X(i,:), ...
        Y(i,:), ...
        '-', ...
        'Color',line_color, ...
        'LineWidth',1, ...
        'HandleVisibility','off');
end

% Points on top.
for it = 1:2

    for i = 1:nwords

        if i<=26
            base_color = edible_color;
        else
            base_color = inedible_color;
        end

        [is_special,pair_idx] = special_word_membership(i,special_pairs);

        if is_special

            shape = special_shapes{pair_idx};

            scatter( ...
                ax, ...
                X(i,it), ...
                Y(i,it), ...
                special_marker_size, ...
                base_color, ...
                'filled', ...
                'Marker',shape, ...
                'MarkerEdgeColor',base_color, ...
                'MarkerFaceColor',base_color, ...
                'LineWidth',0.6, ...
                'HandleVisibility','off');

        else

            scatter( ...
                ax, ...
                X(i,it), ...
                Y(i,it), ...
                normal_marker_size, ...
                base_color, ...
                'filled', ...
                'MarkerEdgeColor','none', ...
                'HandleVisibility','off');
        end
    end
end

% Ellipses around the two sequence windows.
% These ellipses now MATCH the compressed plotting geometry. The point
% clouds themselves are horizontally compressed above via x_compression, so
% the overall layout is truly elliptical rather than only the border.
ellipse_w = 1.10;
ellipse_h = 2.20*y_stretch;

for it = 1:2

    center_x = (it-1)*time_spacing;

    rectangle( ...
        'Parent',ax, ...
        'Position',[ ...
        center_x-ellipse_w/2, ...
        -ellipse_h/2, ...
        ellipse_w, ...
        ellipse_h], ...
        'Curvature',[1 1], ...
        'EdgeColor','k', ...
        'LineStyle','-', ...
        'LineWidth',0.55);
end

% Time arrow.
arrow_y = -1.35*y_stretch;

plot( ...
    ax, ...
    [-0.55 time_spacing+0.55], ...
    [arrow_y arrow_y], ...
    '-', ...
    'Color','k', ...
    'LineWidth',0.8);

plot( ...
    ax, ...
    time_spacing+0.55, ...
    arrow_y, ...
    '>', ...
    'Color','k', ...
    'MarkerFaceColor','k', ...
    'MarkerSize',4);

text( ...
    ax, ...
    time_spacing/2, ...
    arrow_y-0.30*y_stretch, ...
    'Time', ...
    'HorizontalAlignment','center', ...
    'VerticalAlignment','top', ...
    'FontName','Arial', ...
    'FontSize',7);

axis(ax,'equal');
axis(ax,'off');

% Keep enough horizontal room for the compressed elliptical layout.
% Y1/Y2 have unit-radius scaling, so the point clouds can extend to about
% +/-1 around each time center when x_compression=1.
x_extent = max(abs([X(:,1); X(:,2)-time_spacing]));
x_pad = max(0.75,x_extent+0.15);

xlim(ax,[-x_pad time_spacing+x_pad]);
ylim(ax,[-1.78 1.28]*y_stretch);

hold(ax,'off');

end


function [tf,pair_idx] = special_word_membership(word_idx,special_pairs)

tf = false;
pair_idx = NaN;

for ip = 1:size(special_pairs,1)

    if any(special_pairs(ip,:)==word_idx)
        tf = true;
        pair_idx = ip;
        return;
    end
end

end


function [pair_indices,pair_labels] = manual_pair_words_to_indices( ...
    pair_words,word_names,require_true_phonological_pair)
% Convert manually specified word pairs to indices in the 52-word stimulus
% list and optionally require each pair to obey the experiment's i <-> i+26
% phonological-pair definition.

pair_words = string(pair_words);
word_names = string(word_names(:));

assert(size(pair_words,2)==2, ...
    'manual pair specification must have exactly two columns.');

n_pairs = size(pair_words,1);
pair_indices = nan(n_pairs,2);
pair_labels = strings(n_pairs,1);

for ip = 1:n_pairs

    w1 = pair_words(ip,1);
    w2 = pair_words(ip,2);

    idx1 = find(word_names==w1,1,'first');
    idx2 = find(word_names==w2,1,'first');

    assert(~isempty(idx1), ...
        'Manual pair word "%s" was not found in word_names.',w1);
    assert(~isempty(idx2), ...
        'Manual pair word "%s" was not found in word_names.',w2);
    assert(idx1~=idx2, ...
        'A manual pair cannot contain the same word twice: %s.',w1);

    if require_true_phonological_pair
        assert(abs(idx1-idx2)==26, ...
            ['Manual pair "%s / %s" is not a true phonological pair ' ...
             '(expected stimulus indices i and i+26).'],w1,w2);
    end

    pair_indices(ip,:) = [idx1 idx2];
    pair_labels(ip) = w1 + " / " + w2;
end

% Prevent the same word from being highlighted in two different manual pairs.
assert(numel(unique(pair_indices(:)))==numel(pair_indices), ...
    'The manually selected pairs contain a repeated word.');

end


function T = rank_phonological_pairs(group_rdm,word_names,class_name,window_center,window_label)
% Rank the 26 phonologically matched pairs by ascending RDM distance.

n_pairs = 26;

[display_rdm,display_min,display_max] = normalize_rdm_for_display(group_rdm);

pair_index = (1:n_pairs)';
word1_index = pair_index;
word2_index = pair_index + 26;
raw_distance = nan(n_pairs,1);
norm_distance = nan(n_pairs,1);

for i = 1:n_pairs
    raw_distance(i) = group_rdm(word2_index(i),word1_index(i));
    norm_distance(i) = display_rdm(word2_index(i),word1_index(i));
end

% Force every table variable to be an n_pairs x 1 column vector.
% word_names is stored as a 1 x 52 string row vector, and MATLAB can retain
% that row orientation after indexing; reshape here to avoid table row-count
% mismatches.
class_col = repmat(string(class_name),n_pairs,1);
window_center_col = repmat(double(window_center),n_pairs,1);
window_label_col = repmat(string(window_label),n_pairs,1);
word1_col = reshape(string(word_names(word1_index)),[],1);
word2_col = reshape(string(word_names(word2_index)),[],1);
display_min_col = repmat(double(display_min),n_pairs,1);
display_max_col = repmat(double(display_max),n_pairs,1);

assert(all([ ...
    numel(class_col), ...
    numel(window_center_col), ...
    numel(window_label_col), ...
    numel(pair_index), ...
    numel(word1_index), ...
    numel(word2_index), ...
    numel(word1_col), ...
    numel(word2_col), ...
    numel(raw_distance), ...
    numel(norm_distance), ...
    numel(display_min_col), ...
    numel(display_max_col)] == n_pairs), ...
    'Internal error: pair-ranking table columns do not all contain 26 rows.');

T = table( ...
    class_col, ...
    window_center_col, ...
    window_label_col, ...
    pair_index(:), ...
    word1_index(:), ...
    word2_index(:), ...
    word1_col, ...
    word2_col, ...
    raw_distance(:), ...
    norm_distance(:), ...
    display_min_col, ...
    display_max_col, ...
    'VariableNames',{ ...
    'ClassName','WindowCenter_ms','WindowLabel','PairIndex', ...
    'Word1Index','Word2Index','Word1','Word2', ...
    'RawDistance','NormalizedDistance','DisplayMin','DisplayMax'});

T = sortrows(T,{'RawDistance','PairIndex'},{'ascend','ascend'});
T.Rank = (1:height(T))';
T = movevars(T,'Rank','Before','PairIndex');

end


function T = combine_pair_rank_tables(T1,T2)
% Combine pair ranks from P-only and Shared, then choose stable examples.
% Lower combined score = closer in both classes.

A = sortrows(T1,'PairIndex','ascend');
B = sortrows(T2,'PairIndex','ascend');

assert(all(A.PairIndex==B.PairIndex), ...
    'PairIndex mismatch between pair-ranking tables.');

combined_rank = A.Rank + B.Rank;
mean_rank = combined_rank / 2;
mean_norm_distance = mean([A.NormalizedDistance B.NormalizedDistance],2,'omitnan');
mean_raw_distance = mean([A.RawDistance B.RawDistance],2,'omitnan');

T = table( ...
    (1:height(A))', ...
    A.PairIndex, ...
    A.Word1Index, ...
    A.Word2Index, ...
    A.Word1, ...
    A.Word2, ...
    combined_rank, ...
    mean_rank, ...
    A.Rank, ...
    B.Rank, ...
    A.RawDistance, ...
    B.RawDistance, ...
    A.NormalizedDistance, ...
    B.NormalizedDistance, ...
    mean_raw_distance, ...
    mean_norm_distance, ...
    'VariableNames',{ ...
    'CombinedRank','PairIndex','Word1Index','Word2Index','Word1','Word2', ...
    'CombinedScore','MeanRank','Rank_Ponly','Rank_Shared', ...
    'RawDistance_Ponly','RawDistance_Shared', ...
    'NormDistance_Ponly','NormDistance_Shared', ...
    'MeanRawDistance','MeanNormDistance'});

T = sortrows(T,{'CombinedScore','MeanNormDistance','PairIndex'}, ...
    {'ascend','ascend','ascend'});
T.CombinedRank = (1:height(T))';

end


