function p = one_sided_signrank_greater(x)

x = double(x(:));
x = x(isfinite(x));

if isempty(x)

    p = NaN;
    return;
end

if all(abs(x)<eps)

    p = 1;
    return;
end

try

    p = signrank(x,0,'tail','right');

catch

    % Compatibility fallback for releases with stricter syntax.
    p2 = signrank(x,0);

    if median(x,'omitnan')>=0
        p = p2/2;
    else
        p = 1-p2/2;
    end
end

end


function p_adj = adjust_pvalues(p,method)
% Apply the selected correction to one predefined family of p-values.
% In this script this is called separately for 16 P tests and 16 S tests.

method = lower(string(method));

switch method

    case "holm"

        p_adj = holm_adjust(p);

    case "bonferroni"

        p_adj = bonferroni_adjust(p);

    case "fdr"

        p_adj = bh_adjust(p);

    case "none"

        p_adj = p;

    otherwise

        error('Unknown geometry_correction: %s',method);
end

end


function p_adj = holm_adjust(p)
% Holm-Bonferroni adjusted p-values.

was_row = isrow(p);

p = double(p(:));
p_adj = nan(size(p));

valid = isfinite(p);
pv = p(valid);

m = numel(pv);

if m==0

    if was_row
        p_adj = p_adj';
    end

    return;
end

[p_sorted,ord] = sort(pv,'ascend');

adj_sorted = (m-(1:m)'+1).*p_sorted;

for i = 2:m
    adj_sorted(i) = max(adj_sorted(i),adj_sorted(i-1));
end

adj_sorted = min(adj_sorted,1);

adj_valid = nan(m,1);
adj_valid(ord) = adj_sorted;

p_adj(valid) = adj_valid;

if was_row
    p_adj = p_adj';
end

end



function p_adj = bonferroni_adjust(p)

p_adj = double(p);
valid = isfinite(p_adj);
m = nnz(valid);

if m>0
    p_adj(valid) = min(p_adj(valid)*m,1);
end

end


function q = bh_adjust(p)
% Benjamini-Hochberg adjusted p-values.

was_row = isrow(p);

p = double(p(:));
q = nan(size(p));

valid = isfinite(p);
pv = p(valid);

m = numel(pv);

if m==0

    if was_row
        q = q';
    end

    return;
end

[p_sorted,ord] = sort(pv,'ascend');

q_sorted = p_sorted .* m ./ (1:m)';

for i = m-1:-1:1
    q_sorted(i) = min(q_sorted(i),q_sorted(i+1));
end

q_sorted = min(q_sorted,1);

q_valid = nan(m,1);
q_valid(ord) = q_sorted;

q(valid) = q_valid;

if was_row
    q = q';
end

end


function label = correction_label(use_correction,method)

if use_correction
    label = upper(string(method));
else
    label = "NONE";
end

end


function subject_rdms_norm = ...
    normalize_rdm_collection_to_reference(subject_rdms,reference_rdm)
% Normalize all participant RDMs using the SAME min/max as the group RDM
% displayed above the corresponding distance bar plot.
%
% If the displayed group RDM has off-diagonal minimum rmin and maximum rmax:
%
%       R_norm = (R - rmin) / (rmax - rmin)
%
% is applied to every participant RDM in that class/window. This keeps the
% participant-first statistics while placing the bar values on the exact
% normalized scale used by the displayed group RDM.

reference_rdm = complete_rdm(reference_rdm);
mask = tril(true(size(reference_rdm)),-1);
vals = reference_rdm(mask);
vals = vals(isfinite(vals));

if isempty(vals)
    error('Reference RDM contains no finite off-diagonal values.');
end

rmin = min(vals);
rmax = max(vals);

nsub = numel(subject_rdms);
subject_rdms_norm = cell(size(subject_rdms));

for isub = 1:nsub

    R = complete_rdm(subject_rdms{isub});

    if rmax > rmin
        Rn = (R-rmin)/(rmax-rmin);
    else
        Rn = zeros(size(R));
    end

    Rn(1:53:end) = 0;
    subject_rdms_norm{isub} = Rn;
end

end


function s = std_1d(x)

x = double(x(:));
x = x(isfinite(x));

if isempty(x)

    s = NaN;

elseif numel(x)==1

    s = 0;

else

    s = std(x,0);
end

end
